import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetTool 设置工具坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetTool.md","filePath":"3. 指令/5. 设置指令/SetTool.md","lastUpdated":1778862643000}'),s={name:"3. 指令/5. 设置指令/SetTool.md"};function l(n,t,i,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="settool-设置工具坐标系" tabindex="-1">SetTool 设置工具坐标系 <a class="header-anchor" href="#settool-设置工具坐标系" aria-label="Permalink to &quot;SetTool 设置工具坐标系&quot;">​</a></h1><p>该指令用于<strong>设置并切换机器人的当前工具坐标系（TCP）</strong>。它定义了机器人末端执行器（如焊枪、吸盘、抓手）的几何中心点及姿态，确保机器人在运动过程中以正确的工具参考点进行定位和轨迹运动。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetTool(Tool) SetTool(工具参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Tool：工具参数（Tool Param）</td><td>TOOL 变量</td><td>指定当前需要启用的工具坐标系数据。该变量包含了工具相对于机器人末端法兰盘中心的偏移量（X, Y, Z）和旋转角度（RX, RY, RZ）</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>执行此指令后，系统后续所有的运动指令（如 <code>MovL</code>, <code>MovJ</code>）都将基于该 <strong>TOOL</strong> 定义的末端中心点（TCP）进行计算。如果未正确设置，机器人的运动轨迹将偏离预期。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TOOL0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>选择 <strong>TOOL0</strong>（通常为默认法兰中心）作为机器人的当前工具参数。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>多工具切换</strong>：当机器人末端装有换枪装置时，在抓取不同工具后切换对应的坐标系。</li><li><strong>双工位作业</strong>：针对不同的作业任务（如先打磨后抓取），启用不同偏移参数的工具。</li></ul>',18)])])}const b=a(s,[["render",l]]);export{u as __pageData,b as default};
